{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.wtw_analysis as WITH live_date AS ( SELECT distinct SPLIT_PART(id, \'/\', -1) AS id, LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group, MIN(PUBLISHEDAT::date) AS live_date FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value GROUP BY 1,2 having MIN(PUBLISHEDAT::date) > \'2024-10-17\' or MIN(PUBLISHEDAT::date) is null ), sales_data as ( select sku_group, sum(quantity) as gross_quantity from snitch_db.maplemonk.fact_items_snitch where LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and order_timestamp::date >= \'2024-10-17\' and sku_group in (select sku_group from live_date) group by 1 ), clicks as ( select sku_group, sum(clicks) as clicks from snitch_db.maplemonk.clicks_itemid where ga_date >= \'2024-10-17\' and sku_group in (select sku_group from live_date) group by 1 ), app_live_date as ( select sku_group, min(ga_date) as first_published_date from clicks_itemid group by 1 ), metafields as ( select sku_group, material, collar, category, case when print_design in (\'Checks\',\'Gingham, Checks\') then \'Checks\' when print_design in (\'Colourblocked\') then \'Colourblocked\' when print_design in (\'Embroidered\',\'Embellished\') then \'Embroidered, Embellished\' when print_design in (\'Plain\',\'Knitted\') then \'Plain\' when print_design in (\'Printed, Animal Print\',\'Printed, Floral\',\'Printed, Abstract\',\'Geometric, Printed\',\'Printed\',\'Printed, Geometric\',\'Tie & Dye\',\'Floral, Printed\',\'Printed, Polka Dots\',\'Abstract, Printed\',\'Printed \',\'Abstract\',\'Graphic Print\',\'Geometric\',\'Abstract, Marble, Printed\',\'Abstract, Colourblocked, Printed\',\'Abstract, Tie & Dye, Printed\') then \'Print\' when print_design in (\'Textured\',\'Self-Design, Textured, Plain\',\'Textured, Geometric, Self-Design\',\'Self-Design\',\'Textured, Self-Design\',\'Self-Design, Textured\',\'Self-Design, Geometric\') then \'Self-Design, Textured\' when print_design in (\'Stripes\',\'Abstract, Stripes\') then \'Stripes\' else \'others\' end as print, case when fit in (\'Baggy Fit\',\'Relaxed Fit\',\'Loose Fit\',\'Box Fit\',\'Oversized Fit\',\'Comfort Fit\',\'Bootcut\') then \'relaxed\' when fit in (\'Regular Fit\',\'Tapered Fit\',\'Straight Fit\') then \'straight\' when fit in (\'Slim Fit\',\'Skinny Fit\') then \'skinny\' end as fit from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ), wishlist as ( select a.shopify_product_id, b.sku_group, count(*) as wishlist FROM SNITCH_DB.MAPLEMONK.WTW_LIKES a left join live_date b on a.shopify_product_id::varchar = b.id::varchar where request_type = \'launching_soon\' group by 1,2 ), image as ( select sku_group, title, preview_image from snitch_db.maplemonk.products_db_copy qualify row_number() over (partition by sku_group order by status desc ) =1 ) select a.sku_group, case when lower(a.sku_group) like \'%test%\' then \'AI\' else \'NON-AI\' end as type, a.id, a.live_date, coalesce(b.gross_quantity,0) as quant_sold, coalesce(c.clicks,0) as clicks, ald.first_published_date, material, collar, category, print, fit, coalesce(w.wishlist,0) as wishlist, i.preview_image, i.title from live_date a left join sales_data b on a.sku_group = b.sku_group left join clicks c on a.sku_group = c.sku_group left join app_live_date ald on a.sku_group = ald.sku_group left join metafields m on a.sku_group = m.sku_group left join wishlist w on a.id::varchar = w.shopify_product_id::varchar left join image i on a.sku_group = i.sku_group ;",
                    "transaction": true
                }
            ) }}
